let scrollQueued=false;function renderScroll(){scrollQueued=false;const y=scrollY,max=document.documentElement.scrollHeight-innerHeight;$('.progress').style.width=`${max?y/max*100:0}%`;if(!reduced){$('.hero-image').style.transform=`translateY(${Math.min(y,innerHeight)*.16}px) scale(1.025)`;const rect=$('.sea-scene').getBoundingClientRect();if(rect.bottom>0&&rect.top<innerHeight)$('.sea-scene img').style.transform=`translateY(${Math.max(-80,Math.min(80,-rect.top*.1))}px)`;}}addEventListener('scroll',()=>{if(!scrollQueued){scrollQueued=true;requestAnimationFrame(renderScroll)}},{passive:true});renderScroll();
const animations=new WeakMap();function camera(el,target,duration=1100){cancelAnimationFrame(animations.get(el));const start=el.getAttribute('viewBox').split(/\s+/).map(Number);if(reduced){el.setAttribute('viewBox',target.join(' '));return}const t0=performance.now();function tick(t){const p=Math.min(1,(t-t0)/duration),e=1-Math.pow(1-p,4);el.setAttribute('viewBox',target.map((v,i)=>start[i]+(v-start[i])*e).join(' '));if(p<1)animations.set(el,requestAnimationFrame(tick));}animations.set(el,requestAnimationFrame(tick));}
