function showScene(n){scene=n;const s=scenes[n];$('#coast-map').classList.toggle('active',!s[4]);$('#plot-map').classList.toggle('active',s[4]);camera(s[4]?$('#plot-map'):$('#coast-map'),s[3],1250);$('#plot-outline').classList.toggle('visible',n===3);$('#map-count').textContent=`0${n+1} / 04`;$('#map-eyebrow').textContent=`0${n+1} / ${s[0]}`;$('#map-title').textContent=s[1];$('#map-description').textContent=s[2];$('#map-cta').textContent=n===3?'View my unit location':'Click here to zoom';$('#map-sub').textContent=n===3?'Open the original unit location slide':'Follow the journey to your plot';$$('[data-scene]').forEach((b,i)=>b.setAttribute('aria-pressed',String(i===n)));animateContent($('.journey-copy'));}
$$('[data-scene]').forEach(b=>b.onclick=()=>showScene(+b.dataset.scene));$('#map-next').onclick=()=>scene===3?openImage('assets/unit-map-detail.jpg','R1-78 · Unit location and specifications'):showScene(scene+1);
const viewer=$('#viewer'),viewImage=$('#viewer-image');let zoom=1,lastFocus=null;function openImage(src,caption){lastFocus=document.activeElement;zoom=1;viewImage.src=asset(src);viewImage.alt=caption;viewImage.style.width='100%';$('#viewer-caption').textContent=caption;viewer.showModal();document.body.style.overflow='hidden';$('.viewer-canvas').scrollTo(0,0);$('#close-viewer').focus();}function setZoom(z){zoom=Math.max(1,Math.min(5,z));viewImage.style.width=`${zoom*100}%`;$('#zoom-out').disabled=zoom===1;$('#zoom-in').disabled=zoom===5;}$$('[data-image]').forEach(b=>b.onclick=()=>openImage(b.dataset.image,b.dataset.caption||''));$('#close-viewer').onclick=()=>viewer.close();$('#zoom-in').onclick=()=>setZoom(zoom+.5);$('#zoom-out').onclick=()=>setZoom(zoom-.5);viewer.addEventListener('close',()=>{document.body.style.overflow='';lastFocus?.focus({preventScroll:true})});viewer.addEventListener('click',e=>{if(e.target===viewer){const b=viewer.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)viewer.close()}});
const ns='http://www.w3.org/2000/svg';let rooms=[],selectedRoom=-1;
function selectRoom(i){selectedRoom=i;const r=rooms[i],b=r[3];$$('.room-region').forEach((el,n)=>{el.classList.toggle('selected',n===i);el.setAttribute('aria-pressed',String(n===i))});$$('.room-choices button').forEach((el,n)=>el.setAttribute('aria-pressed',String(n===i)));const w=Math.max(b[2]+180,500),h=w*1555/1287;const x=Math.max(0,Math.min(1287-w,b[0]+b[2]/2-w/2)),y=Math.max(0,Math.min(1555-h,b[1]+b[3]/2-h/2));camera($('#floor-camera'),[x,y,w,h],950);$('#room-number').textContent=`${String(i+1).padStart(2,'0')} / VILLA C3`;$('#room-name').textContent=r[0];$('#room-size').textContent=r[1];$('#room-description').textContent=r[2];$('.plan-guidance').textContent='Choose another room · or show full plan';animateContent($('.room-card'));}
function initRooms(data){rooms=data;data.forEach((r,i)=>{const g=document.createElementNS(ns,'g'),rect=document.createElementNS(ns,'rect'),circle=document.createElementNS(ns,'circle'),label=document.createElementNS(ns,'text');g.setAttribute('class','room-region');g.setAttribute('role','button');g.setAttribute('tabindex','0');g.setAttribute('aria-label',`${r[0]}, ${r[1]}. Zoom into room`);g.setAttribute('aria-pressed','false');const [x,y,w,h]=r[3];Object.entries({x,y,width:w,height:h,rx:4}).forEach(([k,v])=>rect.setAttribute(k,v));const cx=x+w/2,cy=y+h/2;Object.entries({cx,cy,r:23}).forEach(([k,v])=>circle.setAttribute(k,v));label.setAttribute('x',cx);label.setAttribute('y',cy);label.textContent=i+1;g.append(rect,circle,label);g.onclick=()=>selectRoom(i);g.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selectRoom(i)}};$('#room-overlays').append(g);const b=document.createElement('button');b.textContent=`${i+1}. ${r[0]}`;b.setAttribute('aria-pressed','false');b.onclick=()=>selectRoom(i);$('#room-choices').append(b)});}
$('#plan-reset').onclick=()=>{selectedRoom=-1;camera($('#floor-camera'),[0,0,1287,1555],900);$$('.room-region').forEach(e=>{e.classList.remove('selected');e.setAttribute('aria-pressed','false')});$$('.room-choices button').forEach(e=>e.setAttribute('aria-pressed','false'));$('#room-number').textContent='YOUR HOME, AT A GLANCE';$('#room-name').textContent='Make yourself at home.';$('#room-size').textContent='4 bedrooms · 245 sqm BUA';$('#room-description').textContent='Choose a room to take a closer look.';$('.plan-guidance').textContent='⊕ Tap a room to explore';};
const money=n=>new Intl.NumberFormat('en-US').format(n);let payments={};function showPlan(key){$$('[data-plan]').forEach(b=>{const yes=b.dataset.plan===key;b.setAttribute('aria-selected',String(yes));b.tabIndex=yes?0:-1});$('#payment-panel').setAttribute('aria-labelledby',`tab-${key}`);$('#price-label').textContent=key==='cash'?'CASH PRICE':`UNIT PRICE / ${key.toUpperCase()} PLAN`;const p=payments[key];$('#price').innerHTML=`${money(key==='cash'?66899762:p.price)}<small> EGP</small>`;
if(key==='cash'){$('#price-details').innerHTML='<div><span>Cash discount</span><b>18,803,238 EGP</b><small>As stated in the original cash offer</small></div>';$('#payment-schedule').innerHTML='<p class="fine">The cash page states the cash price and discount. It does not specify a cash maintenance payment schedule.</p><button class="text-button" id="original-cash">View original cash offer ↗</button>';$('#original-cash').onclick=()=>openImage('assets/page-16.jpg','R1-78 · Original cash offer');}
else{$('#price-details').innerHTML=`<div><span>Down payment</span><b>${money(p.rows[0][2])}</b><small>16 September 2026 · EGP</small></div><div><span>Maintenance</span><b>${money(p.maintenance)}</b><small>EGP · ${p.cheques[1]} maintenance cheques</small></div><div><span>Total including maintenance</span><b>${money(p.total)}</b><small>EGP · ${p.cheques[0]+p.cheques[1]} cheques in total</small></div>`;$('#payment-schedule').innerHTML=`<details class="schedule"><summary>Explore the full ${key==='annual'?'annual':'quarterly'} payment schedule <span>+</span></summary><div class="schedule-scroll" tabindex="0" aria-label="Payment table. Scroll horizontally for all columns."><table><thead><tr>${['Installment','Due date','Unit (EGP)','Percentage','Cumulative','Maintenance','Total due (EGP)'].map(x=>`<th scope="col">${x}</th>`).join('')}</tr></thead><tbody>${p.rows.map(r=>`<tr>${r.map((v,i)=>`<td>${typeof v==='number'?(v===0?'—':money(v)):v}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="fine">${p.cheques[0]} unit cheques + ${p.cheques[1]} maintenance cheques = ${p.cheques[0]+p.cheques[1]} cheques. Amounts and percentages reproduced as issued in the brochure. Scroll sideways to see every column.</p></details>`;}animateContent($('#payment-panel'));}
$$('[data-plan]').forEach((b,i)=>{b.onclick=()=>showPlan(b.dataset.plan);b.onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const j=e.key==='Home'?0:e.key==='End'?2:(i+(e.key==='ArrowRight'?1:2))%3;const next=$$('[data-plan]')[j];next.focus();showPlan(next.dataset.plan)}}});
async function loadData(){const get=async name=>window.embeddedData?.[name]||await fetch(name).then(r=>{if(!r.ok)throw Error(name);return r.json()});try{const data=await Promise.all([get('rooms.json'),get('payments.json')]);initRooms(data[0]);payments=data[1];showPlan('quarterly')}catch(e){$('#room-description').textContent='Open the original plan above to explore every room.';$('#payment-schedule').innerHTML='<p>Download the original offer below to view all payment schedules.</p>';console.error(e)}}loadData();
